#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn dye_colors_preserve_vanilla_ids_names_colors_and_zero_fallback() {
        assert_eq!(VANILLA_DYE_COLORS.len(), 16);
        let mut names = HashSet::new();
        for (id, entry) in VANILLA_DYE_COLORS.iter().enumerate() {
            assert_eq!(entry.color.vanilla_id(), id as u8);
            assert_eq!(VanillaDyeColor::from_vanilla_id(id as i32), entry.color);
            assert!(names.insert(entry.serialized_name));
        }
        assert_eq!(VanillaDyeColor::from_vanilla_id(-1), VanillaDyeColor::White);
        assert_eq!(VanillaDyeColor::from_vanilla_id(16), VanillaDyeColor::White);
        assert_eq!(VanillaDyeColor::White.texture_diffuse_color(), 0xF9FFFE);
        assert_eq!(VanillaDyeColor::White.entry().sheep_wool_color, 0xE6E6E6);
        assert_eq!(VanillaDyeColor::Orange.entry().sheep_wool_color, 0xBA6015);
        assert_eq!(VANILLA_SHEEP_COLOR_DURATION_TICKS, 25);
        assert_eq!(VanillaDyeColor::Red.serialized_name(), "red");
    }

    #[test]
    fn production_sources_do_not_restore_sheep_dye_color_tables() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs")
                    || path.ends_with("bbb-render-types/src/dye_colors.rs")
                    || path.to_string_lossy().contains("/tests/")
                    || path.file_name().and_then(|value| value.to_str()) == Some("tests.rs")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                let compact: String = production
                    .chars()
                    .filter(|character| !character.is_whitespace())
                    .collect();
                if compact.contains("enumVanillaDyeColor{")
                    || compact.contains("enumSheepWoolColor{")
                    || compact.contains("SHEEP_WOOL_LAYER_COLOR_BYTES")
                    || compact.contains("constSHEEP_COLOR_DURATION_TICKS")
                {
                    violations.push(path.display().to_string());
                }
            }
        }
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let mut violations = Vec::new();
        visit(crates, &mut violations);
        assert!(
            violations.is_empty(),
            "parallel sheep dye-color tables: {violations:?}"
        );
    }
}
